/**
 * The pure part of regenerating the built-in statement list: which commits it names, and the
 * text of the generated file.
 * @see specs/lwql/query-origin.feature
 */

/**
 * The covered commits, newest first. A newer fixture commit goes to the front and older
 * versions to the back, so the oldest commit stays the oldest. Blank commits are dropped.
 */
export function mergeCoverageCommits({
  existing,
  newest,
  older,
}: {
  existing: readonly string[];
  newest: string;
  older: readonly string[];
}): string[] {
  const merged = existing.includes(newest) || newest === "" ? [...existing] : [newest, ...existing];
  for (const commit of older) if (commit !== "" && !merged.includes(commit)) merged.push(commit);
  return merged;
}

/** The text of the generated built-in statement list: its covered commits and sorted hashes. */
export function renderBuiltinStatements({
  commits,
  hashes,
}: {
  commits: readonly string[];
  hashes: Iterable<string>;
}): string {
  const oldestCommit = commits.at(-1) ?? "";
  return `// Generated by scripts/generate-lwql-builtin-statements.ts; do not edit. Regenerate with it.
// Covers ${commits.length} stock statement versions, oldest commit ${oldestCommit}. Grow-only: a hash is never removed.

/** What the list covers: the commits whose stock text it holds (newest first), so a reader can tell how far back it goes. */
export const LWQL_BUILTIN_STATEMENT_COVERAGE = {
  versions: ${commits.length},
  oldestCommit: "${oldestCommit}",
  commits: ${JSON.stringify(commits)} as readonly string[],
} as const;

/** sha256 hex of every stock widget statement a saved widget has sent, as written. */
export const LWQL_BUILTIN_STATEMENT_HASHES: readonly string[] = ${JSON.stringify([...hashes].toSorted(), null, 2)};
`;
}
